using System.Linq;
using System.Collections.Generic;

public static class StringExtensions
{
    // 回文判断
    public static bool IsPalindrome(this string s)
    {
        if (string.IsNullOrEmpty(s)) return true;
        var r = new string(s.Reverse().ToArray());
        return s.Equals(r, System.StringComparison.OrdinalIgnoreCase);
    }

    // 泛型约束版 Clamp
    public static T Clamp<T>(this T v, T min, T max) where T : IComparable<T>
        => v.CompareTo(min) < 0 ? min : v.CompareTo(max) > 0 ? max : v;

    // 过滤掉序列中的 null
    public static IEnumerable<T> WhereNotNull<T>(this IEnumerable<T?> source)
        where T : class
        => source.Where(x => x != null)!;
}

// 完整演示
