// 静态虚成员：泛型算法的接口约束（.NET 7 泛型数学）
public interface IAddable<T> where T : IAddable<T>
{
    static abstract T operator +(T left, T right);
}

public readonly record struct Money(decimal Amount, string Currency)
{
    public static Money operator +(Money a, Money b) =>
        a.Currency == b.Currency
            ? new(a.Amount + b.Amount, a.Currency)
            : throw new InvalidOperationException("币种不同，无法相加");

    public static Money operator *(Money m, int times) =>
        new(m.Amount * times, m.Currency);

    public static Money operator -(Money a, Money b) =>
        a.Currency == b.Currency
            ? new(a.Amount - b.Amount, a.Currency)
            : throw new InvalidOperationException("币种不同");

    // 隐式转换：Money -> decimal 金额
    public static implicit operator decimal(Money m) => m.Amount;
}

