using System;

public class Thermometer
{
    // event 限制外部只能订阅/退订，不能随便触发
    public event Action<int>? TemperatureChanged;

    private int _temp;
    public int Temp
    {
        get => _temp;
        set
        {
            _temp = value;
            // ?. 判空后触发，所有订阅者依次收到通知
            TemperatureChanged?.Invoke(value);
        }
    }
}

