public static long Fib(int n)
{
    return fib(n);

    // 本地递归函数：可访问 n，且不分配委托
    long fib(int k) => k <= 1 ? k : fib(k - 1) + fib(k - 2);
}

// 本地迭代器：参数校验立即执行，惰性部分延后（避免"延迟校验陷阱"）
public static IEnumerable<int> Positive(IEnumerable<int> src)
{
    if (src == null) throw new ArgumentNullException(nameof(src)); // 调用即校验
    return Iterator();

    IEnumerable<int> Iterator()
    {
        foreach (var n in src)
            if (n > 0) yield return n;
    }
}

// 完整演示
Console.WriteLine(Fib(10));                       // 55
Console.WriteLine(string.Join(",", Positive(new[] { -1, 2, -3, 4 }))); // 2,4

