// yield break 提前结束；foreach 的 break 会触发 finally/Dispose
static IEnumerable<int> Countdown(int from)
{
    try
    {
        for (int i = from; i > 0; i--)
        {
            if (i == 3) yield break;   // 到 3 直接结束
            yield return i;
        }
    }
    finally
    {
        Console.WriteLine("枚举结束，执行清理");
    }
}

foreach (var n in Countdown(5))
{
    Console.WriteLine(n);             // 5 4
    if (n == 4) break;               // 触发 finally
