// C# 13：params Span（调用点直接栈分配，无数组分配）
static int Max(params ReadOnlySpan<int> values)
{
    int m = values[0];
    foreach (var x in values) if (x > m) m = x;
    return m;
}
Console.WriteLine(Max(3, 1, 4, 1, 5));   // 5

public byte[] Process(int size)
{
    var pool = ArrayPool<byte>.Shared;
    byte[] buffer = pool.Rent(size);       // 租借 ≥ size 的数组（长度可能更大）
    try
    {
        // 内容是脏的，先清零再使用
        Array.Clear(buffer, 0, size);
        Span<byte> slice = buffer.AsSpan(0, size);
        for (int i = 0; i < size; i++) slice[i] = (byte)(i & 0xFF);
        // 只复制实际长度，避免把借来的多余容量带出去
        return slice.ToArray();
    }
    finally
    {
        pool.Return(buffer);               // 必须归还（放 finally，防止异常泄漏）
    }
}

var result = Process(100);
Console.WriteLine($"长度 {result.Length}，首字节 {result[0]}");

[AttributeUsage(AttributeTargets.Method, AllowMultiple = false)]
class BenchmarkAttribute : Attribute
{
    public int Iterations { get; set; } = 1000;
}

class Runner
{
    [Benchmark(Iterations = 5000)]
    public void FastPath() { var s = "abc".Length; _ = s; }

    [Obsolete("请改用 FastPathV2", false)]   // false=仅警告
    public void Legacy() { }
}

// 反射扫描并执行所有标注了 [Benchmark] 的方法
var methods = typeof(Runner).GetMethods()
    .Where(m => m.GetCustomAttribute<BenchmarkAttribute>() != null)
    .ToList();
foreach (var m in methods)
{
    var attr = m.GetCustomAttribute<BenchmarkAttribute>()!;
    Console.WriteLine($"执行 {m.Name} x{attr.Iterations}");
    var instance = new Runner();
    for (int i = 0; i < attr.Iterations; i++)
        m.Invoke(instance, null);
}

